/* ---------- utilidades ---------- */
export const sinTildes = s => String(s).normalize('NFD').replace(/[\u0300-\u036f]/g, '');
export const claveTexto = s => sinTildes(s).toLowerCase().replace(/[^a-zñ0-9]+/g, ' ').replace(/\s+/g, ' ').trim();
// «Talweg (o Vaguada)» → { principal: 'Talweg', variantes: ['Talweg', 'Vaguada'] }
export function analizar(resp) {
  const i = resp.indexOf('('), principal = (i < 0 ? resp : resp.slice(0, i)).replace(/[«»"]/g, '').trim(), vars = [principal];
  if (i >= 0) {
    const dentro = resp.slice(i + 1, resp.lastIndexOf(')') > i ? resp.lastIndexOf(')') : undefined);
    for (const p of dentro.split(/\s*(?:\/|\bo\b|\be\b|\bu\b)\s*/i)) { const t = p.replace(/^(o|e|u)\s+/i, '').replace(/[«»"]/g, '').trim(); if (t && t.length > 1) vars.push(t); }
  }
  return { principal, variantes: [...new Set(vars)] };
}
// la definición no debe delatar la respuesta
export function enmascarar(def, resp) {
  const { variantes } = analizar(resp); let t = def;
  for (const v of variantes) if (claveTexto(v).length > 4) t = t.replace(new RegExp(v.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'), 'gi'), '·····');
  return t;
}
